export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    let observed: number | null = null;

    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: (event: { data?: unknown }) => {
        const data = event?.data as { value?: unknown } | undefined;
        if (data && typeof data.value === 'number') {
          observed = data.value;
        }
      },
    });

    ctx.register({
      kind: 'tool',
      tool: {
        name: 'emit_value',
        version: '1.0.0',
        description: 'Emit a counter.value event with a given value and return the value observed by the local listener.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            value: { type: 'number', description: 'Value to emit on the counter.value event.' },
          },
          required: ['value'],
        },
        outputSchema: {
          type: 'object',
          properties: {
            emitted: { type: 'number' },
            observed: { type: 'number' },
          },
          required: ['emitted', 'observed'],
        },
        async handler(args: unknown) {
          const { value } = args as { value: number };
          observed = null;
          await ctx.bus.emitAsync({ type: 'counter.value', ts: Date.now(), data: { value } });
          return { ok: true, data: { emitted: value, observed } };
        },
      },
    });
  },
};

export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    let observed: number | null = null;

    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: (event: unknown) => {
        const ev = event as { data?: unknown } | number | undefined;
        let v: unknown;
        if (ev && typeof ev === 'object' && 'data' in (ev as object)) {
          v = (ev as { data?: unknown }).data;
        } else {
          v = ev;
        }
        if (v && typeof v === 'object' && 'value' in (v as object)) {
          v = (v as { value?: unknown }).value;
        }
        if (typeof v === 'number') {
          observed = v;
        }
      },
    });

    ctx.register({
      kind: 'tool',
      tool: {
        name: 'emit_value',
        version: '1.0.0',
        description: 'Emit a counter.value event with a given value and return the value observed by the local listener.',
